import{z as l,x as n,o as B,c as D,q as A,j as t,D as a,d as s,s as o,S as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"OTA 更新","description":"","frontmatter":{"title":"OTA 更新","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/emb-ota-updates.md","filePath":"cs/emb-ota-updates.md","lastUpdated":1791413859000}'),i={name:"cs/emb-ota-updates.md"};function C(d,E,p,c,h,m){const e=n("Mermaid");return B(),D("div",null,[E[2]||(E[2]=A('<h1 id="ota-更新" tabindex="-1">OTA 更新 <a class="header-anchor" href="#ota-更新" aria-label="Permalink to &quot;OTA 更新&quot;">​</a></h1><div class="epigraph"><p>更新固件最难的不是传输，而是承诺：无论何时断电、固件多坏，设备醒来都得还能启动。做不到这一点的 OTA，是在给整个机队埋雷。</p><footer>—— 据 MCUboot 设计文档；嵌入式 A/B 分区工程实践整理</footer></div><p><a href="/cs/emb-watchdog-failsafe">上一课</a>让设备能从失效中自行恢复，但恢复到的仍是同一份固件——bug 还在原地。修复最彻底的办法是换固件，而设备已经出厂：焊在外壳里、装在房顶上，插不上调试器。缺口是把「换固件」变成一条<strong>设备自己就能安全走完的路径</strong>：下载、校验、切换、回滚，每一步都要经得起断电。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>闪存不能就地覆盖：写入只能把 1 改成 0，擦除按整块进行，擦过的块全是 1 再逐字写——这套物理在主干课 <a href="/cs/nand-ftl">NAND 闪存与 FTL</a> 讲过，片内闪存同样遵守。于是「更新到一半」不是罕见事故而是必然事件：下载会断，写入时会断电，写完的固件可能根本跑不起来。直接在正在运行的分区上写入，一次断电就把设备变砖——几万台设备的机队里，「必然事件 × 机队规模」等于必然有几台死掉。缺口因此是<strong>把不可事务的写入变成可恢复的流程</strong>：任何时刻断电，设备重启后要么还在跑旧固件，要么跑经验证的新固件，不存在第三种状态。</p><h3 id="双槽与启动裁决" tabindex="-1">双槽与启动裁决 <a class="header-anchor" href="#双槽与启动裁决" aria-label="Permalink to &quot;双槽与启动裁决&quot;">​</a></h3><p>主流答案是双槽 A/B：闪存划出两个固件槽，新固件写进备槽，主槽照常运行；启动代码在每次复位时做裁决——两个槽各验完整性，跑「最新的那个通过校验的」。新固件首次运行后必须主动「确认」自己可用；不确认就复位，引导侧把失败次数记在不掉电的存储里，超过阈值自动回滚旧槽。坏固件若跑挂在死循环里，<a href="/cs/emb-watchdog-failsafe">看门狗与失效安全</a>的复位把它送回裁决点，回滚自然发生——上一课的失效路径在这里接成了升级保险。</p><p><span class="marginnote">「双槽 A/B」就是把闪存划成两个同样大的固件位：A 槽在跑，B 槽当备胎，更新永远只写备胎。代价是固件占用的闪存直接翻倍——用一份固件的空间，换「任何时刻都有一份能跑的版本」这条退路。</span></p>',8)),(B(),t(r,null,{default:a(()=>[o(e,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20DL%5B%22%E4%B8%8B%E8%BD%BD%E6%96%B0%E5%9B%BA%E4%BB%B6%E5%88%B0%E5%A4%87%E6%A7%BD%22%5D%20--%3E%20CRC%5B%22%E6%A0%A1%E9%AA%8C%E5%AE%8C%E6%95%B4%E6%80%A7%E4%B8%8E%E7%89%88%E6%9C%AC%22%5D%0A%20%20CRC%20--%3E%20MARK%5B%22%E7%BD%AE%E8%AF%95%E8%BF%90%E8%A1%8C%E6%A0%87%E8%AE%B0%EF%BC%8C%E5%A4%8D%E4%BD%8D%22%5D%0A%20%20MARK%20--%3E%20DEC%7B%22%E5%90%AF%E5%8A%A8%E8%A3%81%E5%86%B3%EF%BC%9A%E8%B7%91%E6%96%B0%E6%A7%BD%22%7D%0A%20%20DEC%20--%3E%20OK%5B%22%E6%96%B0%E5%9B%BA%E4%BB%B6%E8%87%AA%E6%A3%80%E9%80%9A%E8%BF%87%EF%BC%8C%E5%86%99%E7%A1%AE%E8%AE%A4%E4%BD%8D%22%5D%0A%20%20DEC%20--%3E%20BAD%5B%22%E8%87%AA%E6%A3%80%E5%A4%B1%E8%B4%A5%E6%88%96%E7%9C%8B%E9%97%A8%E7%8B%97%E5%A4%8D%E4%BD%8D%22%5D%0A%20%20BAD%20--%3E%20CNT%7B%22%E5%A4%B1%E8%B4%A5%E6%AC%A1%E6%95%B0%E8%B6%85%E9%98%88%E5%80%BC%3F%22%7D%0A%20%20CNT%20--%3E%7C%22%E5%90%A6%22%7C%20RETRY%5B%22%E5%86%8D%E8%AF%95%E4%B8%80%E6%AC%A1%22%5D%0A%20%20CNT%20--%3E%7C%22%E6%98%AF%22%7C%20ROLL%5B%22%E5%9B%9E%E6%BB%9A%E6%97%A7%E6%A7%BD%22%5D%0A%20%20OK%20--%3E%20DONE%5B%22%E6%9B%B4%E6%96%B0%E5%AE%8C%E6%88%90%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[s(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<p><span class="marginnote">引导加载器是机队里唯一「不能替自己换自己」的部件：它一坏，全机队只能拆机返修。行业惯例是把它的职责压到三条——验槽、数失败次数、选槽启动，代码量压到几 KB，出厂前单独评审。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>落地清单按流程走。传输侧：固件分块下载、逐块写闪存、整体校验（CRC 或哈希），断了从断点续传，版本与机型匹配检查放在下载之前，防止刷错包。写入侧：擦除按块对齐，进度状态写到不掉电的备份寄存器或专门的旗标扇区，写完才改标记——绝不允许「边运行边改自己的槽」。预算侧：片内闪存的擦写寿命典型一万到十万次，<a href="/cs/ssd-gc-wear">SSD 的磨损账</a>在片上同样成立，固件每天自升级一次的设计一年就吃掉几块扇区的寿命；差分升级只传新旧镜像的差量，把射频侧的电量与时间一起省下来。</p><p><span class="marginnote">失败阈值给个具体值：常见做法设 3——新固件连续 3 次没能活着跑过自检，引导侧就回滚旧槽。阈值太小，一次上电电压抖动可能误杀好固件；太大，真坏固件要多把设备折腾几轮才认输。3 是「给偶然留余地、不给故障留时间」的折中。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>整个机制只有一个不变量：<strong>启动裁决是单点控制</strong>。无论断电发生在下载、擦除、写入还是切换的哪一步，复位后控制权都回到引导代码，它按旗标重新计算「该跑哪个槽」——不变量保证所有中间状态都等价于「更新未完成」，旧固件照常可用。切换本身可以做成保守的整槽复制（安全、多花一倍时间）或原位试跑（省擦写、逻辑多一层），取舍由闪存预算决定。确认机制补上「能跑」与「该跑」的差距：镜像校验只证明传输无误，不证明业务正确，能连接上服务器、能读到传感器，才算新固件被接受。</p>',6)),(B(),t(r,null,{default:a(()=>[o(e,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E4%BB%BB%E6%84%8F%E6%97%B6%E5%88%BB%E6%96%AD%E7%94%B5%22%5D%20--%3E%20S1%7B%22%E6%96%AD%E7%94%B5%E5%8F%91%E7%94%9F%E5%9C%A8%E5%93%AA%E4%B8%80%E6%AD%A5%EF%BC%9F%22%7D%0A%20%20S1%20--%3E%7C%22%E4%B8%8B%E8%BD%BD%E4%B8%AD%22%7C%20R1%5B%22%E5%A4%87%E6%A7%BD%E4%B8%8D%E5%AE%8C%E6%95%B4%EF%BC%8C%E4%B8%BB%E6%A7%BD%E5%AE%8C%E5%A5%BD%22%5D%0A%20%20S1%20--%3E%7C%22%E6%93%A6%E5%86%99%E4%B8%AD%22%7C%20R2%5B%22%E6%97%97%E6%A0%87%E6%9C%AA%E7%BD%AE%EF%BC%8C%E8%A3%81%E5%86%B3%E4%BB%8D%E9%80%89%E4%B8%BB%E6%A7%BD%22%5D%0A%20%20S1%20--%3E%7C%22%E8%AF%95%E8%BF%90%E8%A1%8C%E4%B8%AD%22%7C%20R3%5B%22%E7%A1%AE%E8%AE%A4%E4%BD%8D%E6%B2%A1%E5%86%99%E4%B8%8A%EF%BC%8C%E5%A4%B1%E8%B4%A5%E8%AE%A1%E6%95%B0%E5%8A%A0%E4%B8%80%22%5D%0A%20%20S1%20--%3E%7C%22%E7%A1%AE%E8%AE%A4%E4%B9%8B%E5%90%8E%22%7C%20R4%5B%22%E6%96%B0%E5%9B%BA%E4%BB%B6%E5%B7%B2%E6%98%AF%E6%AD%A3%E5%BC%8F%E7%8A%B6%E6%80%81%22%5D%0A%20%20R1%20--%3E%20Z%5B%22%E5%A4%8D%E4%BD%8D%E5%90%8E%E7%85%A7%E5%B8%B8%E8%B7%91%E6%97%A7%E5%9B%BA%E4%BB%B6%22%5D%0A%20%20R2%20--%3E%20Z%0A%20%20R3%20--%3E%20Z2%5B%22%E9%87%8D%E8%AF%95%E6%88%96%E5%9B%9E%E6%BB%9A%EF%BC%8C%E8%AE%BE%E5%A4%87%E4%BB%8D%E5%8F%AF%E7%94%A8%22%5D%0A%20%20R4%20--%3E%20Z3%5B%22%E6%9B%B4%E6%96%B0%E5%B7%B2%E5%AE%8C%E6%88%90%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[s(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<p><span class="marginnote">初学者容易以为「CRC 校验通过」就等于新固件没问题；校验只证明「传输时没写坏」，不证明「代码本身正确」——写坏的数据能通过校验，有 bug 的代码更能。所以才需要试运行加主动确认：跑得起来、连得上服务器，才算数。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课只管「把对的固件安全放进去」；「对的」怎么证明——镜像验签、密钥与信任链——是下一课嵌入式安全的主题，未验签的 OTA 通道等于向所有邻居广播「可以给我写任意代码」。也不写手机与服务器场景：那些有恢复分区与虚拟化兜底，MCU 没有第三份固件替你收拾残局。还有两条：引导加载器自身永不单独升级；多芯片产品要先约定谁先升级、版本如何对表，否则新旧固件对不上协议，功能照样瘫痪。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>闪存不可就地覆盖，更新流程必须把任何断电都等价为「未完成」，这是唯一不变量。</li><li>双槽加启动裁决加试运行确认加失败回滚，构成断电安全与坏固件自救的闭环。</li><li>看门狗复位把挂死的坏固件送回裁决点；确认位补上「能跑」与「该跑」的差距。</li><li>擦写寿命与差分升级是预算侧的两笔账；引导加载器出厂即冻结，职责压到三条。</li><li>出处：MCUboot 项目的设计文档（mcu-tools/mcuboot）；各 MCU 闪存控制器手册；据本栏 nand-ftl、ssd-gc-wear 两课的闪存口径整理。</li></ul>',5))])}const u=l(i,[["render",C]]);export{f as __pageData,u as default};
